let palette = ['#d63230', '#f7d002', '#3275d9', '#f7f7f7', '#0a3977'];
let ctx;
let links = [];

let grid = [];
let cellSize;
let gridRes = 10;

let circles = [];
let strokeThickness;

let bgColor;

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	colorMode(HSB, 360, 100, 100, 100);
	ctx = drawingContext;
	cellSize = width / gridRes;
	let drawingArea = width * 0.75;
	createGridBase(gridRes, drawingArea);
	bgColor = '#ffffff';
	strokeThickness = width * 0.004;

	generate();

}

function draw() {
	background(bgColor);
	for (let i of links) {
		i.run();
	}

	for (let i of circles) {
		i.run();
	}

	if (frameCount % (140) === 0) {
		generate();
	}
}

function generate() {

	links = [];
	circles = [];


	for (let i = 0; i < 20; i++) {
		let c = int(random(3, 10));
		drawLink(c);
	}

	for (let i = 1; i < gridRes; i++) {
		for (let j = 1; j < gridRes; j++) {
			let g = grid[i][j];
			let d = g.w * random(0.25, 0.75);
			let x = g.x - (g.w / 2);
			let y = g.y - (g.w / 2);
			let col = random(palette);
			if (0.5 < random()) {
				circles.push(new Circle(x, y, d));
			}
		}
	}
}

function easeInOutCubic(x) {
	return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
}

function createGridBase(res, area) {
	let w = area / res
	grid = [];
	for (let i = 0; i <= res; i++) {
		grid[i] = [];
		for (let j = 0; j <= res; j++) {
			let x = i * w + (w / 2) + (width - area) / 2;
			let y = j * w + (w / 2) + (width - area) / 2;
			grid[i][j] = {
				x: x,
				y: y,
				w: w
			};
		}
	}
}


function getNextGridIndex(currentCol, currentRow, prevDirection) {
	let oppositeDirection = -1;

	if (prevDirection === 0) {
		oppositeDirection = 2;
	}
	else if (prevDirection === 1) {
		oppositeDirection = 3;
	}
	else if (prevDirection === 2) {
		oppositeDirection = 0;
	}
	else if (prevDirection === 3) {
		oppositeDirection = 1;
	}

	let attemptCount = 0;
	let maxAttempts = 1000;

	while (attemptCount < maxAttempts) {
		attemptCount += 1;
		let stepSize = int(random(1, gridRes / 2));
		let direction = int(random(4));
		if (direction === oppositeDirection) {
			continue;
		}

		let nextX = currentCol + stepSize;
		let nextY = currentRow;

		if (direction === 1) {
			nextX = currentCol;
			nextY = currentRow + stepSize;
		}
		else if (direction === 2) {
			nextX = currentCol - stepSize;
			nextY = currentRow;
		}
		else if (direction === 3) {
			nextX = currentCol;
			nextY = currentRow - stepSize;
		}

		let isOutOfGrid = (nextX < 0) || ((gridRes - 1) < nextX) || (nextY < 0) || ((gridRes - 1) < nextY);
		if (isOutOfGrid) {
			continue;
		}

		return {
			direction: direction,
			nextX: nextX,
			nextY: nextY,
		};
	}

	return {
		direction: prevDirection,
		nextX: currentCol,
		nextY: currentRow,
	};
}

function drawLink(segmentCount) {
	let pathPoints = [];
	let startCol = int(random(gridRes));
	let startRow = int(random(gridRes));
	let startPoint = grid[startCol][startRow];
	pathPoints.push(startPoint);
	let currentCol = startCol;
	let currentRow = startRow;
	let prevDirection = -1;
	for (let i = 0; i < segmentCount; i++) {
		let nextMove = getNextGridIndex(currentCol, currentRow, prevDirection);
		let nextX = nextMove.nextX;
		let nextY = nextMove.nextY;
		prevDirection = nextMove.direction;
		currentCol = nextX;
		currentRow = nextY;
		pathPoints.push(grid[nextX][nextY]);
	}


	links.push(new Link(pathPoints));

}

function drawRoundedPath(pathPoints) {
	if (pathPoints.length < 2) {
		return;
	}

	let cornerRadius = cellSize * 0.375;
	let ctx = drawingContext;

	noFill();
	ctx.beginPath();
	ctx.moveTo(pathPoints[0].x, pathPoints[0].y);

	for (let i = 1; i < pathPoints.length - 1; i++) {
		let currentPoint = pathPoints[i];
		let nextPoint = pathPoints[i + 1];
		ctx.arcTo(currentPoint.x, currentPoint.y, nextPoint.x, nextPoint.y, cornerRadius);
	}

	let endPoint = pathPoints[pathPoints.length - 1];
	ctx.lineTo(endPoint.x, endPoint.y);
	ctx.stroke();
}

/*------------------------------------------------------------------------------------------*/

class Link {
	constructor(pos) {
		this.positions = pos;
		this.totalLength = 0;
		for (let i = 0; i < this.positions.length - 1; i++) {
			let pos1 = this.positions[i];
			let pos2 = this.positions[i + 1];
			this.totalLength += dist(pos1.x, pos1.y, pos2.x, pos2.y);
		}

		this.timer = 0;

		this.offset = -this.totalLength;

		this.duration = int(this.totalLength / 20);

		this.strokeColor = '#000000';
	}

	display() {

		push();
		noFill();
		stroke(this.strokeColor);
		strokeWeight(strokeThickness);
		ctx.setLineDash([this.totalLength, this.totalLength]);
		ctx.lineDashOffset = this.offset;
		drawRoundedPath(this.positions);
		pop();

	}

	update() {
		this.timer++;
		if (0 < this.timer && this.timer < this.duration) {
			let prog = norm(this.timer, 0, this.duration - 1);
			this.offset = lerp(-this.totalLength, 0, easeInOutCubic(prog));
		}
	}

	run() {
		this.display();
		this.update();
	}
}

/*------------------------------------------------------------------------------------------*/

class Circle {
	constructor(x, y, d) {
		this.x = x;
		this.y = y;
		this.d = d;
		this.timer = -int(random(40));
		this.currentDiam = 0;
		this.duration = 40;
		this.fillColor = random(palette);
		this.strokeColor = '#000000';
	}

	display() {
		stroke(this.strokeColor);
		strokeWeight(strokeThickness);
		fill(this.fillColor);
		circle(this.x, this.y, this.currentDiam);
	}

	update() {
		this.timer++;
		if (0 < this.timer && this.timer < this.duration) {
			let prog = norm(this.timer, 0, this.duration - 1);
			this.currentDiam = lerp(0, this.d, easeInOutCubic(prog));
		}
	}

	run() {
		this.display();
		this.update();
	}
}

